// Multiple-choice questions generated by hooks/quiz.py.
//
// Clicking an option commits to it: the choice is marked, the correct answer is
// shown, and the explanation below is revealed. The question then locks, so the
// reader cannot quietly try every option until one goes green — the same
// "commit before you see the answer" idea as the blurred solutions.
//
// A single delegated listener on `document` survives Material's navigation and
// does not need re-binding per page.

function answerQuiz(option) {
  const quiz = option.closest(".quiz");
  if (!quiz || quiz.classList.contains("quiz--answered")) {
    return;
  }

  quiz.classList.add("quiz--answered");
  const correct = option.dataset.correct === "1";
  quiz.classList.add(correct ? "quiz--right" : "quiz--wrong");

  quiz.querySelectorAll(".quiz-option").forEach(function (item) {
    item.setAttribute("tabindex", "-1");
    if (item.dataset.correct === "1") {
      item.classList.add("quiz-option--correct");
    }
  });

  option.classList.add("quiz-option--chosen");
  if (!correct) {
    option.classList.add("quiz-option--wrong");
  }
}

document.addEventListener("click", function (e) {
  const option = e.target.closest(".quiz-option");
  if (option) {
    answerQuiz(option);
  }
});

// Keyboard support: the options are focusable, so Enter and Space should pick
// one just as a click does.
document.addEventListener("keydown", function (e) {
  if (e.key !== "Enter" && e.key !== " ") {
    return;
  }
  const option = e.target.closest(".quiz-option");
  if (option) {
    e.preventDefault();
    answerQuiz(option);
  }
});
